{
  "public_source_descriptions": [
    {
      "id": "basel-plastic-waste-2023",
      "title": "Basel Convention — plastic waste preparation and recycling",
      "url": "https://www.basel.int/Portals/4/download.aspx?d=UNEP-CHW-WAST-GUID-ESM-PlasticWastes-20230512.English.pdf",
      "scope": "General guidance on identifying, preparing and sorting plastic streams and material-specific compatibility. It supplies no binder identity, additive dose or performance prediction for the user's mix."
    },
    {
      "id": "hse-ppis13",
      "title": "HSE — controlling fume during plastics processing",
      "url": "https://www.hse.gov.uk/pubns/ppis13.pdf",
      "scope": "General guidance to identify polymer formulation/additives and processing information before heated processing. Temperature and dwell affect fumes; this is not a heat recipe for unidentified cable residue."
    },
    {
      "id": "hse-slip-assessment",
      "title": "HSE — assessing floor slip resistance",
      "url": "https://www.hse.gov.uk/pubns/geis2.htm",
      "scope": "General floor-slip testing guidance, including instrumented pendulum assessment by a suitably trained operator under relevant surface conditions. It supplies no measured slip value, acceptance target or qualification for the user's recycled material, and no home walking test substitutes for it. Check the current applicable method for the product and installation."
    },
    {
      "id": "osha-combustible-dust",
      "title": "OSHA — combustible dust overview",
      "url": "https://www.osha.gov/combustible-dust",
      "scope": "Some metals in fine form can present combustible-dust issues. Ask for metal identity, particle form and suitable existing handling controls; do not assume all metal dust is combustible or reject every batch."
    },
    {
      "id": "nist-weighing-tare",
      "title": "NIST — weighing and scales FAQs",
      "url": "https://www.nist.gov/pml/owm/faqs/weighing-and-scales-faqs",
      "scope": "General weighing/tare guidance supports weighing the complete assembly including its enclosure. Scale capability and measurement uncertainty must suit the target tolerance; display resolution alone does not establish accuracy. This does not establish enclosure strength, fill retention or product qualification."
    },
    {
      "id": "cecon2021",
      "title": "Cecon 2021 — measured recycled-PE blends",
      "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC8517156/",
      "scope": "The study's PE blends and injection process only. It illustrates measuring a response at separate recycled-content levels, not a density or recipe for another material."
    },
    {
      "id": "rapa2020",
      "title": "Râpă 2020 — modifiers and filler in recycled PP",
      "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC7040787/",
      "scope": "The study's separate recycled-PP/elastomer/glass-bubble formulations only. It illustrates formulation tradeoffs, not transferable binder amounts or predicted performance."
    }
  ],
  "initial_prompt": "I want to make an indoor floor mat from recycled rubber and a binder. The amount of paper-label residue in the rubber varies. How can I decide what to try while keeping grip and recovery within my targets and watching the cost?",
  "initial_case": {
    "product_and_use": "Synthetic indoor floor mat for the same intended use and nominal dimensions in all setups.",
    "materials_and_variation": "Identified recycled rubber stock with paper-label residue; the amount of named paper varies. The available zero-paper added stock is characterized clean rubber, with 0 percent paper by mass. All amounts, fractions and prices in this exercise use the same as-received mass basis.",
    "process_and_equipment": "Home planning only. No physical handling, processing, measuring equipment, or lab access is available during this exercise. The same intended process and geometry are stated for each setup but unspecified.",
    "property_checks": [
      {
        "id": "grip",
        "name": "wet grip",
        "unit": "coefficient",
        "synthetic_method": "Synthetic method G under the same stated conditions",
        "minimum": "0.60",
        "required": true
      },
      {
        "id": "recovery",
        "name": "recovery",
        "unit": "%",
        "synthetic_method": "Synthetic method R under the same stated conditions",
        "minimum": "80",
        "required": true
      }
    ],
    "setups": [
      {
        "setup": "A",
        "version": 1,
        "materials_kg": {
          "recycled rubber excluding paper": "9.5",
          "paper-label residue": "0.5",
          "binder": "1.5"
        },
        "process": "same intended process; unspecified",
        "geometry": "same intended mat; unspecified",
        "historical": true
      },
      {
        "setup": "A",
        "version": 2,
        "materials_kg": {
          "recycled rubber excluding paper": "9.5",
          "paper-label residue": "0.5",
          "binder": "1.75"
        },
        "process": "same intended process; unspecified",
        "geometry": "same intended mat; unspecified",
        "historical": false
      },
      {
        "setup": "B",
        "version": 1,
        "materials_kg": {
          "recycled rubber excluding paper": "9.5",
          "paper-label residue": "0.5",
          "binder": "0.5"
        },
        "process": "same intended process; unspecified",
        "geometry": "same intended mat; unspecified",
        "historical": false
      }
    ],
    "readings": [
      {
        "setup": "A",
        "version": 1,
        "check": "grip",
        "value": "0.66",
        "kind": "synthetic",
        "grouping": "unknown"
      },
      {
        "setup": "A",
        "version": 2,
        "check": "recovery",
        "value": "82",
        "kind": "synthetic",
        "grouping": "unknown"
      },
      {
        "setup": "B",
        "version": 1,
        "check": "grip",
        "value": "0.55",
        "kind": "synthetic",
        "grouping": "unknown"
      },
      {
        "setup": "B",
        "version": 1,
        "check": "recovery",
        "value": "85",
        "kind": "synthetic",
        "grouping": "unknown"
      }
    ],
    "costs": {
      "currency": "CU",
      "mass_basis": "as received",
      "material_prices_CU_per_kg": {
        "recycled rubber excluding paper": "2",
        "paper-label residue": "0",
        "binder": "4"
      },
      "cost_scope": "Materials only; energy, labor and all other costs are explicitly excluded.",
      "output_basis": "The same intended mat and use in both cases; usable output counts are synthetic planning entries.",
      "planning_entry": "Use planning scenario mode; enter gross planned item counts 8 and 7 for A2 and B1 respectively, with assumed accepted fraction 1 for both. This is a calculation assumption, not measured yield or proof of usability.",
      "usable_mats": {
        "A version 2": "8",
        "B version 1": "7"
      }
    }
  },
  "independent_calculator_costs": {
    "A version 2": {
      "material_amounts_kg": {
        "recycled rubber excluding paper": "9.5",
        "paper-label residue": "0.5",
        "binder": "1.75"
      },
      "prices_CU_per_kg": {
        "recycled rubber excluding paper": "2",
        "paper-label residue": "0",
        "binder": "4"
      },
      "formula": "sum(component kg * price per kg) / assumed usable mats",
      "materials_CU_per_batch": "26.00",
      "assumed_usable_mats": "8",
      "CU_per_usable_mat": "3.25"
    },
    "B version 1": {
      "material_amounts_kg": {
        "recycled rubber excluding paper": "9.5",
        "paper-label residue": "0.5",
        "binder": "0.5"
      },
      "prices_CU_per_kg": {
        "recycled rubber excluding paper": "2",
        "paper-label residue": "0",
        "binder": "4"
      },
      "formula": "sum(component kg * price per kg) / assumed usable mats",
      "materials_CU_per_batch": "21.0",
      "assumed_usable_mats": "7",
      "CU_per_usable_mat": "3.0"
    }
  },
  "question": "Using the synthetic readings and materials-only costs, what can I choose now, what is missing, and what could I plan next at home?"
}
